def gcd(a, b):
	if b == 0:
		return a
	return gcd(b, a % b)

def exgcd(a, b):
	if b == 0:
		x = 1
		y = 0
		return (a, x, y)
	(ret, x, y) = exgcd(b, a % b)
	tmp = x
	x = y
	y = tmp - int(a / b) * y
	return (ret, x, y)

